 const C=()=>chars.find(c=>c.id===st.c);const isMe=id=>PC.same(id,st.c);const KIT=()=>KC[st.c]||{abilities:[]};const TEAMS=()=>PC.teams(coach,st.c);
 const TM=()=>{const L=TEAMS();return L.find(t=>t.key===st.team)||L[0]};
