 function easyList(){if(easyList.L)return easyList.L;const L=[],gk=(PC.GEAR[0]||[])[2];chars.forEach(c=>{const v=(c.inv&&c.inv[gk])||{};PC.teams(coach,c.id).forEach(t=>{let S=null;try{S=PC.select(coach,{char:c.id,team:t.key,cons:0,tc:Object.assign({},t.defaults),gear:{weapon:v.weapon,set:(v.art||{}).set,pcs:(v.art||{}).pcs},variant:'',r:''})}catch(e){}if(!S||!S.ok)return;const acts=S.actions.filter(a=>!a.skip),r=S.rot,cond=acts.filter(a=>a.optional||(a.branch_conditions||[]).length||(a.required_conditions||[]).length).length,ass=(r.key_assumptions||[]).length;L.push({c,t,r,n:acts.length,cond,ass,score:ass*10+cond*2+acts.length})})});L.sort((a,b)=>a.score-b.score||a.n-b.n||String(a.c.name).localeCompare(b.c.name));return easyList.L=L}
